    (SELECT COUNT(DISTINCT CustomerID) 
     FROM yearmonth 
     WHERE CustomerID IN (SELECT CustomerID FROM customers WHERE Segment = 'LAM')
       AND Consumption > 46.73
    ) * 100.0 / (SELECT COUNT(*) FROM customers WHERE Segment = 'LAM') AS PercentLAMConsumedAbove46_73;
